package com.musicplaylist.controller;
import com.musicplaylist.util.*;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.sql.*;
@WebServlet("/songs/add") public class SongServlet extends HttpServlet {protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Integer uid=Auth.userId(q);if(uid==null){p.sendRedirect(q.getContextPath()+"/login");return;}try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement("INSERT INTO songs(title,artist,album,genre,added_by) VALUES(?,?,?,?,?)")){s.setString(1,q.getParameter("title"));s.setString(2,q.getParameter("artist"));s.setString(3,q.getParameter("album"));s.setString(4,q.getParameter("genre"));s.setInt(5,uid);s.executeUpdate();p.sendRedirect(q.getContextPath()+"/dashboard");}catch(SQLException x){throw new ServletException(x);}}}